// Generated from src/registry/sources/control-ui/recipes/table-of-contents.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const tableOfContentsKnobs = [
  "--cui-table-of-contents-rail-background",
  "--cui-table-of-contents-highlight-radius",
  "--cui-table-of-contents-highlight-background",
] as const;
export type TableOfContentsKnobStyle = Partial<Record<(typeof tableOfContentsKnobs)[number], string>>;

@layer components {
  :where([data-control-family="table-of-contents"][data-slot="root"]) {
    --cui-track-highlight-transition-duration: var(--duration-base);
    --cui-table-of-contents-rail-background: oklch(from var(--border) l c h / 0.6);
    --cui-table-of-contents-highlight-radius: var(--radius-md);
    --cui-table-of-contents-highlight-background: oklch(from var(--foreground) l c h / 0.04);
    border: 1px solid oklch(from var(--border) l c h / 0.7);
    border-radius: var(--radius-panel);
    background-color: oklch(from var(--card) l c h / 0.8);
    box-shadow: var(--shadow-sm);
    backdrop-filter: blur(var(--blur-sm));
    font-size: var(--text-sm);
  }

  :where([data-control-family="table-of-contents"][data-slot="label"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
    font-weight: 500;
  }

  :where([data-control-family="table-of-contents"][data-slot="rail"]) {
    background-color: var(--cui-table-of-contents-rail-background);
  }

  :where([data-control-family="table-of-contents"][data-slot="item"]) {
    color: var(--muted-foreground);
    font-size: var(--text-sm);
    font-weight: 400;
    transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="table-of-contents"][data-slot="item"][data-depth="0"]) {
    font-weight: 500;
  }

  @media (hover: hover) {
    :where([data-control-family="table-of-contents"][data-slot="item"]:hover) {
      color: var(--foreground);
    }
  }

  :where([data-control-family="table-of-contents"][data-slot="item"]:focus-visible) {
    color: var(--foreground);
  }

  :where([data-control-family="table-of-contents"][data-slot="item"][data-active]) {
    color: var(--foreground);
  }

  :where([data-control-family="table-of-contents"][data-slot="root"] [data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-radius: var(--cui-table-of-contents-highlight-radius);
    --cui-track-highlight-background: var(--cui-table-of-contents-highlight-background);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  :where([data-control-family="table-of-contents"][data-slot="root"][data-variant="trail"]) {
    --cui-table-of-contents-highlight-radius: 0px;
    --cui-table-of-contents-highlight-background: transparent;
  }

  :where([data-control-family="table-of-contents"][data-slot="trail"]) {
    border-radius: 9999px;
    background-color: var(--foreground);
  }
}

@property --cui-table-of-contents-rail-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-table-of-contents-highlight-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-table-of-contents-highlight-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { useEffect, useState } from "react";
import { TrackHighlight } from "@/components/control-ui/extensions/track-highlight";
import type { TableOfContentsKnobStyle } from "@/components/control-ui/knob-contracts/table-of-contents-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type TocItem = {
  href: string;
  label: string;
  level?: number;
  children?: TocItem[];
};

export const tableOfContentsVariants = ["background", "trail", "both"] as const;

export type TableOfContentsVariant = (typeof tableOfContentsVariants)[number];

export type TableOfContentsProps = Omit<Omit<ComponentProps<"nav">, "children">, "style"> & {
  style?: CSSProperties & TableOfContentsKnobStyle;
} & {
  items: TocItem[];
  label?: string;
  variant?: TableOfContentsVariant;
};

const DETECTION_MARGIN = "-80px 0px -20% 0px";
const indentByDepth = ["pl-3", "pl-5", "pl-7", "pl-9", "pl-11", "pl-14"] as const;

const TOC_ITEM_SELECTOR = '[data-control-ui="table-of-contents"][data-slot="item"]';
const TOC_ACTIVE_SELECTOR = '[data-control-ui="table-of-contents"][data-slot="item"][data-active]';

const tableOfContentsItemClass = "block py-1.5";
const tableOfContentsHighlightClass = "";
const tableOfContentsTrailClass = "absolute inset-y-0 left-0 w-0.5";

function getScrollContainer(el: HTMLElement): HTMLElement | null {
  let node = el.parentElement;
  while (node) {
    if (/(auto|scroll|overlay)/.test(getComputedStyle(node).overflowY)) return node;
    node = node.parentElement;
  }
  return null;
}

export function useVisibleSections(ids: string[]): string[] {
  const [visibleState, setVisibleState] = useState<{ idsKey: string; visibleIds: string[] }>({ idsKey: "", visibleIds: [] });
  const idsKey = ids.join("|");

  useEffect(() => {
    const idList = idsKey ? idsKey.split("|") : [];
    const elements = idList.map((id) => document.getElementById(id)).filter((el): el is HTMLElement => el !== null);
    const firstElement = elements[0];
    if (!firstElement) return;

    const order = new Map(elements.map((el, index) => [el.id, index]));
    const visible = new Set<string>();

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) visible.add(entry.target.id);
          else visible.delete(entry.target.id);
        }
        setVisibleState({
          idsKey,
          visibleIds: [...visible].sort((a, b) => (order.get(a) ?? 0) - (order.get(b) ?? 0)),
        });
      },
      { root: getScrollContainer(firstElement), rootMargin: DETECTION_MARGIN, threshold: 0 },
    );

    for (const el of elements) observer.observe(el);
    return () => observer.disconnect();
  }, [idsKey]);

  return visibleState.idsKey === idsKey ? visibleState.visibleIds : [];
}

type TocNode = Omit<TableOfContentsProps["items"][number], "children" | "level"> & {
  depth: number;
  level: number;
  children?: TocNode[];
};

function collectLevels(items: TableOfContentsProps["items"], fallbackLevel = 2): number[] {
  return items.flatMap((item) => {
    const level = item.level ?? fallbackLevel;
    return [level, ...collectLevels(item.children ?? [], level + 1)];
  });
}

function normalizeItems(items: TableOfContentsProps["items"], baseLevel: number, fallbackLevel = 2, nestingDepth = 0): TocNode[] {
  return items.map((item) => {
    const level = item.level ?? fallbackLevel;
    const depth = Math.max(nestingDepth, Math.max(0, level - baseLevel));
    const nestedItems = item.children;
    const children =
      nestedItems && nestedItems.length > 0 ? normalizeItems(nestedItems, baseLevel, level + 1, nestingDepth + 1) : undefined;

    return {
      ...item,
      level,
      depth,
      children,
    };
  });
}

function flattenItems(items: TocNode[]): TocNode[] {
  return items.flatMap((item) => [item, ...flattenItems(item.children ?? [])]);
}

function itemIndentClass(depth: number) {
  return indentByDepth[Math.min(depth, indentByDepth.length - 1)];
}

function activeIdsInRange(visibleIds: string[], targetIds: string[]) {
  let firstIndex = targetIds.length;
  let lastIndex = -1;

  for (const id of visibleIds) {
    const index = targetIds.indexOf(id);
    if (index < 0) continue;
    firstIndex = Math.min(firstIndex, index);
    lastIndex = Math.max(lastIndex, index);
  }

  if (lastIndex < 0) return new Set<string>();
  return new Set(targetIds.slice(firstIndex, lastIndex + 1));
}

export function TableOfContents({ items, label = "On this page", variant = "both", className, style, ...props }: TableOfContentsProps) {
  const baseLevel = Math.min(...collectLevels(items), 2);
  const normalizedItems = normalizeItems(items, baseLevel);
  const flatItems = flattenItems(normalizedItems);
  const targetIds = flatItems.map((item) => item.href.replace(/^#/, ""));
  const visibleIds = useVisibleSections(targetIds);
  const activeSet = activeIdsInRange(visibleIds, targetIds);
  const railStyle = style;
  const highlightStyle = style;

  if (items.length === 0) return null;

  return (
    <nav
      data-control-ui="table-of-contents"
      data-control-family="table-of-contents"
      data-slot="root"
      data-variant={variant}
      aria-label={label}
      className={cn("sticky top-6 p-4", className)}
      style={style}
      {...props}
    >
      <p data-control-ui="table-of-contents" data-control-family="table-of-contents" data-slot="label" className="mb-3">
        {label}
      </p>
      <div data-control-ui="table-of-contents" data-control-family="table-of-contents" data-slot="track" className="relative isolate">
        <span
          aria-hidden
          data-control-ui="table-of-contents"
          data-control-family="table-of-contents"
          data-slot="rail"
          className="pointer-events-none absolute inset-y-0 left-0 -z-20 w-px"
          style={railStyle}
        />
        <TrackHighlight
          data-variant={variant}
          itemSelector={TOC_ITEM_SELECTOR}
          activeSelector={TOC_ACTIVE_SELECTOR}
          range
          followHover={false}
          style={highlightStyle}
          className={tableOfContentsHighlightClass}
        >
          {variant !== "background" && (
            <div
              aria-hidden
              data-control-ui="table-of-contents"
              data-control-family="table-of-contents"
              data-slot="trail"
              className={tableOfContentsTrailClass}
            />
          )}
        </TrackHighlight>
        <TocList items={normalizedItems} activeSet={activeSet} variant={variant} root />
      </div>
    </nav>
  );
}

function TocList({
  items,
  activeSet,
  variant,
  root = false,
}: {
  items: TocNode[];
  activeSet: Set<string>;
  variant: TableOfContentsVariant;
  root?: boolean;
}) {
  return (
    <ul
      data-control-ui="table-of-contents"
      data-control-family="table-of-contents"
      data-slot="list"
      data-nested={root ? undefined : "true"}
    >
      {items.map((item) => {
        const targetId = item.href.replace(/^#/, "");
        const isActive = activeSet.has(targetId);

        return (
          <li key={item.href}>
            <a
              data-control-ui="table-of-contents"
              data-control-family="table-of-contents"
              data-slot="item"
              data-active={isActive || undefined}
              data-variant={variant}
              data-level={item.level}
              data-depth={item.depth}
              aria-current={isActive ? "location" : undefined}
              href={item.href}
              className={cn(tableOfContentsItemClass, itemIndentClass(item.depth))}
            >
              {item.label}
            </a>
            {item.children && <TocList items={item.children} activeSet={activeSet} variant={variant} />}
          </li>
        );
      })}
    </ul>
  );
}
